window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-0a236ea4304fad49"]={"versions": [{"id": "FIG-0a236ea4304fad49", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Software Component Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm spezifiziert die Metamodell-Struktur der Klasse <code>ApplicationValueSpecification</code> (spezialisiert aus <code>ValueSpecification</code>) zur modellhaften Definition von physikalischen Applikations- und Kalibrierwerten (z. B. Kennwerte, Kennlinien, Kennfelder) innerhalb des M1-Modells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationValueSpecification</code>: Spezialisiert <code>ValueSpecification</code>. Besitzt das Attribut <code>+ category : Identifier</code>. Es aggregiert über Kompositionen:</li>\n<li><code>+swAxisCont</code> [0..*] {ordered}: Zielklasse <code>SwAxisCont</code>.</li>\n<li><code>+swValueCont</code> [0..1]: Zielklasse <code>SwValueCont</code>.</li>\n<li><code>SwAxisCont</code>: Repräsentiert Achsenbeschreibungen von Kalibrierparametern. Attribute:</li>\n<li><code>+ category : CalprmAxisCategoryEnum</code></li>\n<li><code>+ swAxisIndex : AxisIndexType</code></li>\n</ul>\n<p class=\"fig-p\">Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>+swArraysize</code> [1] auf <code>ValueList</code>.</li>\n<li><code>+swValuesPhys</code> [1] auf <code>SwValues</code>.</li>\n<li><code>SwValueCont</code>: Repräsentiert den eigentlichen Wertecontainer. Kompositionen:</li>\n<li><code>+swArraysize</code> [0..1] auf <code>ValueList</code>.</li>\n<li><code>+swValuesPhys</code> [0..1] auf <code>SwValues</code>.</li>\n<li><code>ValueList</code> («atpMixed»): Liste von Array-Größen bzw. Dimensionen. Attribute:</li>\n<li><code>+ v : Numerical</code></li>\n<li><code>«atpVariation» + vf : Numerical [0..*] {ordered}</code></li>\n<li><code>SwValues</code> («atpMixed»): Container für physikalische Werte. Attribute:</li>\n<li><code>+ v : Numerical</code></li>\n<li><code>+ vt : VerbatimString</code></li>\n<li><code>«atpVariation» + vf : Numerical</code></li>\n</ul>\n<p class=\"fig-p\">Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>+vg</code> [1] auf <code>ValueGroup</code>.</li>\n<li><code>«atpVariation» +vtf</code> [1] auf <code>NumericalOrText</code>.</li>\n<li><code>ValueGroup</code>: Gruppierungselement für strukturierte Wertemengen. Rekursive Komposition:</li>\n<li><code>+vgContents</code> [0..1] von <code>ValueGroup</code> zurück auf <code>SwValues</code>.</li>\n<li><code>+label</code> [0..1] auf <code>MultilanguageLongName</code>.</li>\n<li><code>MultilanguageLongName</code>: Mehrsprachige Bezeichnung für Wertgruppen.</li>\n<li><code>NumericalOrText</code>: Variante zur Darstellung einzelner Werte. Attribute:</li>\n<li><code>+ vt : String [0..1]</code></li>\n<li><code>«atpVariation» + vf : Numerical [0..1]</code></li>\n<li>Annotations-Notiz zur Assoziation <code>+vtf</code>: <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Klassendiagramm der AUTOSAR-Metamodell-Struktur stellt die Abbildung keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe zur Laufzeit dar. Sie definiert die hierarchische Datenorganisation zur statischen Konfiguration und Modellierung von Werten vor der Code-Generierung bzw. zur Parametrierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Definition von Initialwerten und Kalibriergrößen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationValueSpecification</code> unterstützt sowohl skalare als auch mehrdimensionale Datenstrukturen über geordnete Achsen (<code>SwAxisCont</code>) und Wertblöcke (<code>SwValueCont</code>).</li>\n<li>Durch das Stereotyp «atpMixed» an <code>ValueList</code> und <code>SwValues</code> sowie «atpVariation» an <code>vf</code> und der Aggregation <code>+vtf</code> wird AUTOSAR-Variabilität auf Modell- und Wertebene unterstützt.</li>\n<li>Die spätmöglichste Bindungszeit (<code>vh.latestBindingTime</code>) für die Variation an <code>vtf</code> ist fest als <code>preCompileTime</code> vorgegeben.</li>\n<li>Bei der Serialisierung in ARXML ist die geordnete Reihenfolge (<code>{ordered}</code>) der Achsencontainer und variablen Zahlenwerte verbindlich einzuhalten.</li>\n</ul>"}, {"id": "FIG-c16183bb2710d370", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm aus der AUTOSAR-Spezifikation des Software Component Templates (<code>AUTOSAR_TPS_SoftwareComponentTemplate</code>). Das Diagramm spezifiziert die Metamodell-Struktur der Klasse <code>ApplicationValueSpecification</code> (spezialisiert aus <code>ValueSpecification</code>) zur modellhaften Definition von physikalischen Applikations- und Kalibrierwerten (z. B. Kennwerte, Kennlinien, Kennfelder) innerhalb des M1-Modells.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Klassendiagramm umfasst folgende Entitäten, Attribute und Relationen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationValueSpecification</code>: Spezialisiert <code>ValueSpecification</code>. Besitzt das Attribut <code>+ category : Identifier</code>. Es aggregiert über Kompositionen:</li>\n<li><code>+swAxisCont</code> [0..*] {ordered}: Zielklasse <code>SwAxisCont</code>.</li>\n<li><code>+swValueCont</code> [0..1]: Zielklasse <code>SwValueCont</code>.</li>\n<li><code>SwAxisCont</code>: Repräsentiert Achsenbeschreibungen von Kalibrierparametern. Attribute:</li>\n<li><code>+ category : CalprmAxisCategoryEnum</code></li>\n<li><code>+ swAxisIndex : AxisIndexType</code></li>\n</ul>\n<p class=\"fig-p\">Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>+swArraysize</code> [1] auf <code>ValueList</code>.</li>\n<li><code>+swValuesPhys</code> [1] auf <code>SwValues</code>.</li>\n<li><code>SwValueCont</code>: Repräsentiert den eigentlichen Wertecontainer. Kompositionen:</li>\n<li><code>+swArraysize</code> [0..1] auf <code>ValueList</code>.</li>\n<li><code>+swValuesPhys</code> [0..1] auf <code>SwValues</code>.</li>\n<li><code>ValueList</code> («atpMixed»): Liste von Array-Größen bzw. Dimensionen. Attribute:</li>\n<li><code>+ v : Numerical</code></li>\n<li><code>«atpVariation» + vf : Numerical [0..*] {ordered}</code></li>\n<li><code>SwValues</code> («atpMixed»): Container für physikalische Werte. Attribute:</li>\n<li><code>+ v : Numerical</code></li>\n<li><code>+ vt : VerbatimString</code></li>\n<li><code>«atpVariation» + vf : Numerical</code></li>\n</ul>\n<p class=\"fig-p\">Kompositionen:</p>\n<ul class=\"fig-list\">\n<li><code>+vg</code> [1] auf <code>ValueGroup</code>.</li>\n<li><code>«atpVariation» +vtf</code> [1] auf <code>NumericalOrText</code>.</li>\n<li><code>ValueGroup</code>: Gruppierungselement für strukturierte Wertemengen. Rekursive Komposition:</li>\n<li><code>+vgContents</code> [0..1] von <code>ValueGroup</code> zurück auf <code>SwValues</code>.</li>\n<li><code>+label</code> [0..1] auf <code>MultilanguageLongName</code>.</li>\n<li><code>MultilanguageLongName</code>: Mehrsprachige Bezeichnung für Wertgruppen.</li>\n<li><code>NumericalOrText</code>: Variante zur Darstellung einzelner Werte. Attribute:</li>\n<li><code>+ vt : String [0..1]</code></li>\n<li><code>«atpVariation» + vf : Numerical [0..1]</code></li>\n<li>Annotations-Notiz zur Assoziation <code>+vtf</code>: <code>«atpVariation» Tags: vh.latestBindingTime = preCompileTime</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Als rein statisches UML-Klassendiagramm der AUTOSAR-Metamodell-Struktur stellt die Abbildung keine dynamischen Interaktionen, Zustandsübergänge oder Sequenzabläufe zur Laufzeit dar. Sie definiert die hierarchische Datenorganisation zur statischen Konfiguration und Modellierung von Werten vor der Code-Generierung bzw. zur Parametrierung.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ relevant für die Definition von Initialwerten und Kalibriergrößen:</p>\n<ul class=\"fig-list\">\n<li><code>ApplicationValueSpecification</code> unterstützt sowohl skalare als auch mehrdimensionale Datenstrukturen über geordnete Achsen (<code>SwAxisCont</code>) und Wertblöcke (<code>SwValueCont</code>).</li>\n<li>Durch das Stereotyp «atpMixed» an <code>ValueList</code> und <code>SwValues</code> sowie «atpVariation» an <code>vf</code> und der Aggregation <code>+vtf</code> wird AUTOSAR-Variabilität auf Modell- und Wertebene unterstützt.</li>\n<li>Die spätmöglichste Bindungszeit (<code>vh.latestBindingTime</code>) für die Variation an <code>vtf</code> ist fest als <code>preCompileTime</code> vorgegeben.</li>\n<li>Bei der Serialisierung in ARXML ist die geordnete Reihenfolge (<code>{ordered}</code>) der Achsencontainer und variablen Zahlenwerte verbindlich einzuhalten.</li>\n</ul>"}], "trans": [{"from": "FIG-0a236ea4304fad49", "to": "FIG-c16183bb2710d370", "fr": "R4.1.3", "tr": "R4.2.2", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
